"""B05 resource wire proof, generated by real SQLite/Library/Collection/API."""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from server.app.models.library import ArtworkRef, Song
from server.tests.support.playback import real_client, run  # noqa: F401

FIXTURE = Path(__file__).resolve().parents[3] / "web/tests/fixtures/library.json"


def test_library_web_fixture_from_real_resources(real_client, monkeypatch):  # noqa: F811
    client, repository, _, _ = real_client
    monkeypatch.setattr("server.app.repositories.library_repository._now", lambda: "2026-10-11T00:00:00+00:00")
    monkeypatch.setattr("server.app.repositories.library_repository.uuid.uuid4", lambda: "album-wire")
    for song_id in "abc":
        run(repository.upsert_song(Song(
            song_id=song_id, title="长标题 / " + song_id, file_uri=f"{song_id}.flac",
            artists=("艺术家 / 长名",), album_id="album-wire", album="长专辑",
            album_artists=("专辑艺术家",), genres=("Rock",), tag_names=("Live",),
            year=2024, track_number={"a": 2, "b": 1, "c": 3}[song_id],
            availability_status="MISSING" if song_id == "c" else "AVAILABLE",
        )))
    actual = {}
    for kind in ("songs", "albums", "artists", "genres", "years", "tags"):
        response = client.get(f"/api/library/{kind}")
        assert response.status_code == 200, response.text
        actual[kind] = response.json()
    actual["albums"] = client.get("/api/library/albums").json()
    actual["album_songs"] = client.get("/api/library/albums/album-wire/songs").json()
    response = client.post("/api/library/collections", json={"source_type": "ALBUM", "source_id": "album-wire"})
    assert response.status_code == 200, response.text
    actual["collection"] = response.json()
    assert [s["song_id"] for s in actual["songs"]["items"]] == ["a", "b", "c"]
    assert actual["collection"]["song_ids"] == ["b", "a"]
    assert actual["collection"]["unavailable_song_ids"] == ["c"]
    assert [s["song_id"] for s in actual["album_songs"]["items"]] == ["b", "a"]
    assert FIXTURE.exists(), "B05 real resource golden fixture is missing"
    assert json.loads(FIXTURE.read_text()) == actual


@pytest.mark.parametrize("route", [
    "/api/library/songs/a",
    "/api/library/songs",
    "/api/library/albums/album-artwork/songs",
])
def test_non_null_artwork_preserves_song_and_resource_identity(
    real_client, route, monkeypatch,  # noqa: F811
):
    client, repository, _, _ = real_client
    monkeypatch.setattr(
        "server.app.repositories.library_repository.uuid.uuid4",
        lambda: "album-artwork",
    )
    artwork = {
        "artwork_id": "embedded-cover-a",
        "source": "EMBEDDED",
        "picture_index": 2,
        "mime_type": "image/png",
        "width": 320,
        "height": 240,
        "content_sha256": "a" * 64,
    }
    run(repository.upsert_song(Song(
        song_id="a", title="非空封面", file_uri="A/曲目.flac",
        album_id="album-artwork", album="封面专辑",
        artwork=ArtworkRef(**artwork),
        lyrics="保留歌词", lyrics_format="text",
        lyrics_source="embedded", lyrics_status="available",
    )))
    persisted = run(repository.get_song("a"))
    assert persisted is not None
    assert persisted.artwork is not None
    assert persisted.artwork.model_dump() == artwork
    assert persisted.album_id == "album-artwork"
    response = client.get(route)
    assert response.status_code == 200, response.text
    body = response.json()
    public_song = body if route.endswith("/songs/a") else next(
        song for song in body["items"] if song["song_id"] == "a"
    )
    assert public_song["artwork"] == artwork
    assert public_song["song_id"] == "a"
    assert public_song["file_uri"] == "A/曲目.flac"
    assert public_song["album_id"] == "album-artwork"
    assert public_song["title"] == "非空封面"
    assert public_song["availability_status"] == "AVAILABLE"
    assert public_song["lyrics"] == "保留歌词"
    assert public_song["lyrics_status"] == "available"
    assert "identity_key" not in public_song
    album_response = client.get("/api/library/albums")
    assert album_response.status_code == 200, album_response.text
    album = next(item for item in album_response.json()["items"]
                 if item["album_id"] == "album-artwork")
    assert album["artwork"] == artwork
    collection = client.post("/api/library/collections", json={
        "source_type": "ALBUM", "source_id": "album-artwork",
    })
    assert collection.status_code == 200, collection.text
    assert collection.json()["song_ids"] == ["a"]
    assert run(repository.get_song("a")) == persisted
